package com.learnagent.digest;
import com.learnagent.websearch.ResourceQualityReviewer;

import com.learnagent.analysis.AnalysisService;import com.learnagent.course.*;import com.learnagent.job.AgentJobService;import com.learnagent.learning.*;import com.learnagent.notification.*;import com.learnagent.task.*;import com.learnagent.websearch.WebSearchProvider;import com.learnagent.workspace.WorkspaceFileService;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class DailyDigestService{private final DailyDigestRepository digests;private final ExternalResourceRepository resources;private final StudyTaskRepository tasks;private final LearningSessionRepository sessions;private final AnalysisService analysis;private final CourseService courses;private final WebSearchProvider web;private final WorkspaceFileService files;private final NotificationService notifications;private final AgentJobService jobs;private final HiddenResourceSourceRepository hidden;private final ZoneId zone;public DailyDigestService(DailyDigestRepository d,ExternalResourceRepository r,StudyTaskRepository t,LearningSessionRepository s,AnalysisService a,CourseService c,WebSearchProvider w,WorkspaceFileService f,NotificationService n,AgentJobService j,HiddenResourceSourceRepository hidden,@Value("${learnagent.time-zone:Asia/Shanghai}")String zone){this.hidden=hidden;digests=d;resources=r;tasks=t;sessions=s;analysis=a;courses=c;web=w;files=f;notifications=n;jobs=j;this.zone=ZoneId.of(zone);}@Transactional public DigestView generateToday(){return generate(LocalDate.now(zone));}@Transactional public DigestView generate(LocalDate date){Optional<DailyDigest>existing=digests.findByDigestDate(date);if(existing.isPresent())return view(existing.get());return jobs.run("DAILY_DIGEST","daily-"+date,Map.of("date",date.toString()),ctx->{ctx.progress(15,"Selecting active learning topics");Topic topic=topic();ctx.progress(35,"Searching public learning resources");List<WebSearchProvider.WebSearchResult>found=web.isConfigured()?safeSearch(topic.query()):List.of();String relative="_inbox/"+date+"/daily-digest.md";String markdown=markdown(date,topic,found);files.write(relative,markdown);ctx.progress(70,"Saved Markdown digest to D-drive workspace");DailyDigest digest=digests.save(new DailyDigest(date,topic.courseId(),topic.query(),relative,"围绕“"+topic.query()+"”整理了 "+found.size()+" 条外部学习资料。"+(found.size()<5?"本次符合条件的新资料不足 5 条，不用重复资料补足。":"")));for(var item:found){resources.save(new ExternalResource(digest.getId(),topic.courseId(),item.title(),item.url(),item.sourceName(),item.snippet(),item.publishedAt(),relative).reviewed(item.review()));}notifications.create(NotificationType.DAILY_DIGEST,"今日学习资料已准备","已整理 "+found.size()+" 条与当前任务和薄弱点相关的资料。","/workbench?path="+relative,"DAILY_DIGEST",digest.getId(),"daily-"+date);ctx.progress(95,"Created inbox notification");return view(digest);});}@Transactional(readOnly=true)public DigestView latest(){return digests.findFirstByOrderByDigestDateDesc().map(this::view).orElse(null);}@Transactional(readOnly=true)public List<DigestView>list(){return digests.findAllByOrderByDigestDateDesc().stream().map(this::view).toList();}private List<WebSearchProvider.WebSearchResult>safeSearch(String query){try{
  List<WebSearchProvider.WebSearchResult> history=resources.findAllByOrderByDiscoveredAtDesc().stream()
      .map(r->new WebSearchProvider.WebSearchResult(r.getTitle(),r.getSummary(),r.getUrl(),r.getSourceName(),r.getPublishedAt())).toList();
  Set<String> blocked=new HashSet<>(hidden.findAll().stream().map(HiddenResourceSource::getHost).toList());
  var candidates=web.search(query,5,history).stream().filter(r->!blocked.contains(ResourceQualityReviewer.host(r.url()))).toList();
  return com.learnagent.websearch.ResourceSelection.select(query,candidates,history,5,Instant.now());
}catch(RuntimeException ignored){return List.of();}}private Topic topic(){List<StudyTask>pending=new ArrayList<>();pending.addAll(tasks.findByStatus(TaskStatus.TODO));pending.addAll(tasks.findByStatus(TaskStatus.IN_PROGRESS));pending.sort(Comparator.comparing(StudyTask::getDueAt,Comparator.nullsLast(Comparator.naturalOrder())));List<String>parts=new ArrayList<>();pending.stream().limit(2).map(StudyTask::getTitle).forEach(parts::add);analysis.weakPoints(null).stream().limit(2).map(AnalysisService.WeakPoint::knowledgePoint).forEach(parts::add);sessions.findAllByOrderByUpdatedAtDesc().stream().filter(s->s.getStatus()!=LearningSessionStatus.STOPPED).limit(1).map(LearningSession::getGoal).forEach(parts::add);UUID courseId=pending.stream().map(StudyTask::getCourseId).filter(Objects::nonNull).findFirst().orElseGet(()->sessions.findAllByOrderByUpdatedAtDesc().stream().map(LearningSession::getCourseId).findFirst().orElseGet(()->courses.list().stream().map(Course::getId).findFirst().orElse(null)));if(parts.isEmpty())parts.add("Java 与计算机基础学习");return new Topic(courseId,String.join("；",parts.stream().distinct().limit(4).toList()));}private String markdown(LocalDate date,Topic topic,List<WebSearchProvider.WebSearchResult>found){StringBuilder text=new StringBuilder("# ").append(date).append(" 每日学习资料\n\n").append("> 推荐依据：近期任务、测验薄弱点与活跃学习目标。\n\n## 今日主题\n\n").append(topic.query()).append("\n\n## 推荐资料\n\n");if(found.size()<5)text.append("本次符合条件的新资料不足 5 条（可能受搜索可用性、相关性、来源过滤或历史去重影响），仅展示实际找到的资料。\n\n");if(found.isEmpty())text.append("当前没有通过正文审核的新资料（可能为搜索/抓取/模型不可用、正文超长、质量不符或历史去重），请继续使用课程资料。\n");for(int i=0;i<found.size();i++){var item=found.get(i);text.append("### ").append(i+1).append(". ").append(item.title()).append("\n\n").append(item.snippet()).append("\n\n- 来源：[").append(item.sourceName()).append("](").append(item.url()).append(")\n");if(item.review()!=null)text.append("- 自动审查：").append(item.review().status()).append("；推荐排序分：").append(item.review().score()).append("\n- 推荐依据：").append(item.review().reason()).append("\n");if(item.publishedAt()!=null)text.append("- 发布时间：").append(item.publishedAt()).append("\n");text.append("- 整理时间：").append(Instant.now()).append("\n\n");}text.append("## 建议行动\n\n1. 选择一条资料阅读并记录三个要点。\n2. 回到 LearnAgent 让 Agent 解释不理解的概念。\n3. 完成后启动一轮5题测试。\n");return text.toString();}private DigestView view(DailyDigest digest){Set<String> blocked=new HashSet<>(hidden.findAll().stream().map(HiddenResourceSource::getHost).toList());return new DigestView(digest.getId(),digest.getDigestDate(),digest.getCourseId(),digest.getTopic(),digest.getMarkdownPath(),digest.getSummary(),digest.getCreatedAt(),resources.findByDigestId(digest.getId()).stream().filter(r->!blocked.contains(ResourceQualityReviewer.host(r.getUrl()))).map(r->new ResourceView(r.getTitle(),r.getUrl(),r.getSourceName(),r.getSummary(),r.getPublishedAt(),r.getDiscoveredAt(),r.getReviewScore(),r.getReviewStatus(),r.getReviewReason())).toList());}private record Topic(UUID courseId,String query){}public record ResourceView(String title,String url,String sourceName,String summary,Instant publishedAt,Instant discoveredAt,Integer reviewScore,String reviewStatus,String reviewReason){}public record DigestView(UUID id,LocalDate date,UUID courseId,String topic,String markdownPath,String summary,Instant createdAt,List<ResourceView>resources){} }
